import {test} from 'vite-plus/test';
import assert from 'node:assert/strict';
import {fixture} from './fixture.mjs';
import {readString} from '../../web/memory.mjs';

// Generated by macOS Foundation NSKeyedArchiver, with repeated mutable-object references.
const foundationArchive = Buffer.from('', 'base64');
async function data(x, bytes) {
  const pointer=x.heap.alloc(bytes.length);x.cpu.write(pointer,bytes);
  try{return await x.send(x.cls('NSData'),'dataWithBytes:length:',pointer,bytes.length);}
  finally{x.heap.free(pointer);}
}
test('decodes native Foundation containers, scalar types and object identity with owned lifetimes',async t=>{
  const x=await fixture(t),pool=x.f('_objc_autoreleasePoolPush');
  const root=await x.send(x.cls('NSKeyedUnarchiver'),'unarchiveObjectWithData:',await data(x,foundationArchive));
  await x.send(root,'retain');
  const string=s=>x.send(x.cls('NSString'),'stringWithUTF8String:',x.heap.string(s));
  const entry=async key=>x.send(root,'objectForKey:',await string(key));
  const array=await entry('array'),first=await x.send(array,'objectAtIndex:',0);
  assert.equal(await x.send(array,'objectAtIndex:',1),first);
  assert.equal(await x.send(await x.send(array,'objectAtIndex:',2),'intValue'),7);
  assert.equal(await x.send(await x.send(array,'objectAtIndex:',3),'boolValue'),0);
  assert.equal(await x.send(await entry('set'),'count'),2);
  const bytes=await entry('data');
  assert.equal(new TextDecoder().decode(x.cpu.read(await x.send(bytes,'bytes'),await x.send(bytes,'length'))),'bytes');
  const bits=new DataView(new ArrayBuffer(8));
  bits.setBigUint64(0,await x.send(await entry('date'),'timeIntervalSinceReferenceDate'),true);
  assert.equal(bits.getFloat64(0,true),12.5);
  await x.f('_objc_autoreleasePoolPop',pool);
  assert.equal(readString(x.cpu,await x.send(first,'UTF8String')),'shared');
  await x.send(root,'release');
  assert.equal(x.heap.live.has(first),false);
  assert.equal(x.heap.live.has(root),false);
});
test('missing archive files return nil but malformed data fails explicitly',async t=>{
  const x=await fixture(t,()=>{},new Map(),{sys:{funcs:{_open:()=>-1}}});
  const path=await x.send(x.cls('NSString'),'stringWithUTF8String:',x.heap.string('/Documents/missing.archive'));
  assert.equal(await x.send(x.cls('NSKeyedUnarchiver'),'unarchiveObjectWithFile:',path),0);
  await assert.rejects(x.send(x.cls('NSKeyedUnarchiver'),'unarchiveObjectWithData:',await data(x,Buffer.from('bad'))),/plist/i);
});

const customArchive = Buffer.from('', 'base64');
test('guest initWithCoder callbacks decode typed scalars, missing keys and a self reference',async t=>{
  let x, visited=0;
  x=await fixture(t,async(pc,args)=>{
    assert.equal(pc,0x6300);visited++;
    const [self,,coder]=args;
    const key=s=>x.send(x.cls('NSString'),'stringWithUTF8String:',x.heap.string(s));
    assert.equal(await x.send(coder,'decodeObjectForKey:',await key('self')),self);
    assert.equal(await x.send(coder,'decodeIntForKey:',await key('count')),-8);
    assert.equal(await x.send(coder,'decodeBoolForKey:',await key('enabled')),1);
    assert.equal(await x.send(coder,'containsValueForKey:',await key('missing')),0);
    assert.equal(await x.send(coder,'decodeIntForKey:',await key('missing')),0);
    assert.equal(await x.send(coder,'decodeObjectForKey:',await key('missing')),0);
    const bits=new DataView(new ArrayBuffer(8));
    bits.setBigUint64(0,await x.send(coder,'decodeDoubleForKey:',await key('ratio')),true);
    assert.equal(bits.getFloat64(0,true),1.5);
    return self;
  });
  const cls=x.instance('RetroveArchiveNode',[['initWithCoder:',0x6300]]);
  x.install({'__objc_classlist':[cls]});
  const root=await x.send(x.cls('NSKeyedUnarchiver'),'unarchiveObjectWithData:',await data(x,customArchive));
  assert.equal(x.read(root),cls);assert.equal(visited,1);
});
